HEALTH = "Nutrition, health and food-safety statements are textbook-level and conservative: a dietitian, food scientist or health worker must review them before release."
KJ = {"c": 17, "p": 17, "f": 37}
def mkpack(pid, title, level, exam, ref, desc):
    return Pack(pid, title, level=level, subject="sciences", cursus="secondary", exam=exam, wanted="food-science", programRef=ref, description=desc)

# computations
bmi = lambda w, h: w / (h * h)
assert round(bmi(70, 1.75), 1) == 22.9 and round(bmi(85, 1.60), 1) == 33.2 and round(bmi(50, 1.70), 1) == 17.3
assert 70 * 24 == 1680 and round(1680 * 4.2) == 7056 and round(1680 * 1.4) == 2352
assert 0.75 / 5 * 100 == 15.0 and 100 - (15 + 3 + 20 + 5) == 57 and 57 * 17 + 20 * 17 + 5 * 37 == 1494
assert 0.32 * 6.25 == 2.0 and 100 * 2 ** (180 // 30) == 6400
assert 1 * 3 - 1 == 2

